create table till_sessions(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),till_id uuid not null,opened_by uuid not null references users(id),closed_by uuid references users(id),opening_float numeric(12,2) not null check(opening_float>=0),closing_count numeric(12,2),expected_cash numeric(12,2),discrepancy numeric(12,2),discrepancy_reason text,opened_at timestamptz not null default now(),closed_at timestamptz,foreign key(organisation_id,till_id) references tills(organisation_id,id),unique(organisation_id,id));
create unique index one_open_session_per_till on till_sessions(till_id) where closed_at is null;
create index till_sessions_org_idx on till_sessions(organisation_id,opened_at desc);
create table cash_movements(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisations(id),session_id uuid not null,movement_type text not null check(movement_type in('paid_in','paid_out')),amount numeric(12,2) not null check(amount>0),reason text not null,created_by uuid not null references users(id),created_at timestamptz not null default now(),foreign key(organisation_id,session_id) references till_sessions(organisation_id,id));
create index cash_movements_session_idx on cash_movements(session_id,created_at);
alter table sales add column till_session_id uuid references till_sessions(id);
do $$ declare n text; begin foreach n in array array['till_sessions','cash_movements'] loop execute format('alter table %I enable row level security',n);execute format('alter table %I force row level security',n);execute format('create policy tenant_isolation on %I for all using (organisation_id=(select app_current_organisation_id())) with check (organisation_id=(select app_current_organisation_id()))',n);end loop;end $$;
grant select,insert,update on till_sessions,cash_movements to counter_app;
